  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + OrderQuantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

class Manufacturer {
  + Name : string
}

class Availability {
  + IsAvailable : boolean
}

